import React, { useEffect, useState } from "react";



import { getStore, updStore, gen16CodeId,  ObjectKeys, setIntervalX} from "../../../stores/Utils";

import {SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import {  TimeCardItem_Cmpt } from "..";
import {   getall_timecard, parseTimeClock,  search_timecard } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";



const SearchInput = SearchInput_Cmpt();


const TimeCardItem = TimeCardItem_Cmpt();

const coll2list = "time_cards_list"


const TimeCardDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);
	const [range, set_range] = useState(64);

	const [loading, set_loading] = useState(false);




	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			get_balances_by_type("global_accounts","global_account_params",handle_getall);
			updStore("cmpByPayStubMayor",{})
			
		}
	});



	
	const openAddView =  () => {
		let data = {};
		data["zIndex"] = 450;
		data["height"] = "80vh";
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		// data["content"] = <AddTimeCard confimr={handle_getall_employee} />
		OpenModal(data);
	}


	const importCSV =  (event) => {
		var fileReader = new FileReader();
		fileReader.onload = function(fileLoadedEvent){
			var textFromFileLoaded = fileLoadedEvent.target.result;
			parseTimeClock(textFromFileLoaded)
			loadList();
		};
		fileReader.readAsText(event.target.files[0], "UTF-8");
	}

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}


	const handle_search =  (v) => {
		set_loading(true)

		let qrs = getStore("searchQryTC").split(" ")
		search_timecard(qrs,loadList)

	}


	const handle_getall =  () => {
		getall_timecard(loadList)
	}

	


	const cb_result = async (f, v) => {
		if(range!==64){
			set_range(64);
		}
		else{
			set_obs(gen16CodeId())
		}
	};


	const loadMore=  () => {
		set_range(v=>v+64)
	}


	
	const loadList =  () => {

		
		let docdata = getStore("timecard_list");
				
		updStore(coll2list,docdata);
		
		cb_result();

		let factor = Math.ceil(docdata.length / 64);

		setIntervalX(loadMore, 1250, factor)

		
		setTimeout(() => {
			set_loading(false)
		}, 230);
		
	};
	

	return (

		<div className="">
			<div className="accounts_header">
				<h2>TimeCard</h2>
				<div className="_dsplFlx ">
					<div className="group_title addBtn purple upl">
						Importar Time Card
						<input id="fileupload" type = "file" onChange={importCSV}/>
					</div>
				</div>
				<div className="_dsplFlx " style={{marginTop:14}}>
					<SearchInput
							placeholder={"Buscar ...."} 
							width={360}
							obs={set_obs}
							fetchData={handle_search}
							loading={loading}
							change={handleChange}
							callempty={handle_getall}
							keyFlds={"searchQryTC"}
						/>
					<div className="flexSpace"/>
					<div className="_dsplFlx ">
						<div className="total_comprobante_title" >
							No: 
						</div>
						<div className="total_comprobante gray" >
							<span>
								{ObjectKeys(getStore(coll2list))?.length}
							</span>
						</div>
						
					</div>
				</div>
			</div>
			<div className="timeCard_container scollVh">
			{getStore("timeCard") && ObjectKeys(getStore("timeCard"))?.map(cid=>{
				return (
					<TimeCardItem 
						data={getStore("timeCard")[cid]} 
						elmId={cid} 
						key={cid}
						handleRefreshAll={handle_getall}
						add={true}
					/>
				)
			})}
			{getStore(coll2list) && ObjectKeys(getStore(coll2list))?.map(cid=>{
				return (
					<TimeCardItem 
						data={getStore(coll2list)[cid]} 
						elmId={cid} 
						key={cid}
						handleRefreshAll={handle_getall}
					/>
				)
			})}
			</div>
		</div>
	);
};

export default TimeCardDashboard;
